'use strict';
function stopAudio(){playGeneration++;if(audioPlayer){audioPlayer.pause();audioPlayer=null}if(audioUrl){URL.revokeObjectURL(audioUrl);audioUrl=null}if('speechSynthesis'in window)speechSynthesis.cancel()}
async function speak(id,practice=false){const p=state.phrases.find(x=>x.id===id);if(!p)return;stopAudio();const generation=playGeneration;if(!practice){state.uses.push({id,date:new Date().toISOString()});persist()}let saved;try{if(recordingIds.has(id))saved=await getRecording(id)}catch{toast('Could not open that recording. Try recording it again.');return}if(generation!==playGeneration)return;
 if(saved){audioUrl=URL.createObjectURL(saved.blob);audioPlayer=new Audio(audioUrl);try{await audioPlayer.play();toast('Playing '+(p.recordedBy||state.profile.caregiver)+'’s recording.')}catch{toast('Audio could not play. Tap Say it aloud to try again.')}return}
 if(!('speechSynthesis'in window)){toast('This browser has no device voice. Add a family recording in the studio.');return}
 const u=new SpeechSynthesisUtterance(practice&&session?.type==='words'?p.label:p.phrase);u.lang='en-GB';u.rate=Number(state.profile.pace)||.8;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-GB'&&v.localService)||voices.find(v=>v.lang.startsWith('en')&&v.localService)||null;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('Device voice unavailable. Add a family recording in the studio.')};speechSynthesis.speak(u);toast('English device preview · Record your own household phrase.');
}
function showModal(title,body){if(modal.open)closeModal();$('#modal-body').innerHTML='<div class="modal-content"><div class="modal-header"><h2 id="modal-title">'+title+'</h2><button class="icon-button" data-action="close" aria-label="Close dialog">'+icon('close')+'</button></div>'+body+'</div>';modal.setAttribute('aria-labelledby','modal-title');modal.showModal()}
function cleanupRecording(){if(mediaRecorder?.state==='recording'){mediaRecorder.onstop=null;mediaRecorder.stop()}if(mediaStream)mediaStream.getTracks().forEach(t=>t.stop());mediaStream=null;mediaRecorder=null;clearInterval(recordTimer);if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl=null}pendingBlob=null}
function closeModal(){cleanupRecording();modal.close()}
function settingsModal(){showModal('Our household.','<p class="modal-description">Make the space yours. The language setting labels your recordings; it does not translate the English samples.</p><form id="settings-form"><div class="form-grid"><label class="field">Person using Sauti<input name="patient" required maxlength="40" value="'+esc(state.profile.patient)+'"></label><label class="field">Caregiver’s name<input name="caregiver" required maxlength="30" value="'+esc(state.profile.caregiver)+'"></label></div><label class="field">Our household language<input name="language" required maxlength="40" list="languages" value="'+esc(state.profile.language)+'"><datalist id="languages">'+['Kikuyu','Swahili','Luo','Kalenjin','Kamba','Luhya','English','Somali','Meru'].map(x=>'<option value="'+x+'">').join('')+'</datalist></label><label class="field">English preview pace<select name="pace"><option value="0.65" '+(state.profile.pace===.65?'selected':'')+'>Extra gentle</option><option value="0.8" '+(state.profile.pace===.8?'selected':'')+'>Gentle</option><option value="1" '+(state.profile.pace===1?'selected':'')+'>Natural</option></select></label><div class="modal-actions"><button type="button" class="secondary-button" data-action="close">Cancel</button><button class="primary-button" type="submit">Save our space '+icon('check')+'</button></div></form>')}
function phraseModal(id){const p=state.phrases.find(x=>x.id===id);pendingPhoto=undefined;showModal(p?'A phrase that feels familiar.':'Add a little piece of home.','<p class="modal-description">Choose a useful phrase and a recognisable picture. Use your household’s own wording.</p><form id="phrase-form" data-id="'+esc(id||'')+'"><div class="form-grid"><label class="field">Button label<input name="label" required maxlength="30" value="'+esc(p?.label||'')+'" placeholder="A cup of tea"></label><label class="field">Category<select name="category">'+['Essentials','Comfort','People','Feelings'].map(c=>'<option '+(p?.category===c?'selected':'')+'>'+c+'</option>').join('')+'</select></label></div><label class="field">What would you like to say?<textarea name="phrase" rows="2" required maxlength="250" placeholder="I would like a cup of tea.">'+esc(p?.phrase||'')+'</textarea></label><label class="field">First-sound or starting cue (optional)<input name="cue" maxlength="80" value="'+esc(p?.cue||'')+'" placeholder="The first sound, in your language"></label><div class="form-grid"><label class="field">Picture symbol<select name="symbol">'+Object.keys(drawings).map(s=>'<option value="'+s+'" '+(p?.symbol===s?'selected':'')+'>'+s[0].toUpperCase()+s.slice(1)+'</option>').join('')+'</select></label><label class="field">Or add a personal photo<input id="photo-upload" class="file-input" type="file" accept="image/png,image/jpeg,image/webp"></label></div><p class="field-hint" id="photo-status">'+(p?.photo?'A personal photo is saved for this phrase.':'Photos are resized and stored on this device.')+'</p><div class="modal-actions">'+(p?'<button type="button" class="danger-button" data-action="delete-phrase" data-id="'+esc(p.id)+'">Remove phrase</button>':'')+'<button type="button" class="secondary-button" data-action="close">Cancel</button><button class="primary-button" type="submit">Save phrase '+icon('check')+'</button></div></form>')}
async function recordModal(id){const p=state.phrases.find(x=>x.id===id);if(!p)return;stopAudio();const has=recordingIds.has(id);showModal('A voice that feels like home.','<p class="modal-description">Say the phrase in '+esc(state.profile.language)+', just as you would at home. Speak clearly and leave a small pause at each end.</p><section class="record-area"><p class="eyebrow">'+esc(p.label)+'</p><h3>'+esc(p.phrase)+'</h3><p>Recording as '+esc(state.profile.caregiver)+' · '+esc(state.profile.language)+'</p><button id="record-toggle" class="record-button" data-action="toggle-record" aria-label="Start recording">'+icon('mic')+'</button><div id="record-status" class="record-status" role="status">Tap the microphone when you’re ready.</div><audio id="record-preview" controls hidden aria-label="Preview recording"></audio></section><label class="field">Or choose an audio file<input type="file" id="audio-upload" accept="audio/*" class="file-input"></label><p class="field-hint">Up to 5 MB. A short phrase is plenty.</p><div class="modal-actions">'+(has?'<button class="danger-button" data-action="remove-recording" data-id="'+esc(id)+'">Remove recording</button>':'')+'<button class="secondary-button" data-action="close">Cancel</button><button id="save-recording" class="primary-button" data-action="save-recording" data-id="'+esc(id)+'" disabled>Save this voice '+icon('check')+'</button></div>');
 if(has){try{const rec=await getRecording(id);if(!modal.open||!$('#record-preview')||!rec)return;recordUrl=URL.createObjectURL(rec.blob);$('#record-preview').src=recordUrl;$('#record-preview').hidden=false;$('#record-status').textContent='Your saved voice. Record again to replace it.'}catch{toast('Saved recording could not be opened.')}}
}
async function toggleRecord(){if(mediaRecorder?.state==='recording'){mediaRecorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('#record-status').textContent='Microphone recording is unavailable here. Choose an audio file below.';return}
 const button=$('#record-toggle');button.disabled=true;
 try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});if(!modal.open||!$('#record-toggle')){cleanupRecording();return}mediaRecorder=new MediaRecorder(mediaStream);const chunks=[];mediaRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};mediaRecorder.onstop=()=>{const blob=new Blob(chunks,{type:mediaRecorder.mimeType||'audio/webm'});mediaStream.getTracks().forEach(t=>t.stop());mediaStream=null;clearInterval(recordTimer);if(blob.size>5*1024*1024){$('#record-status').textContent='That recording is too large. Try a shorter phrase.';return}pendingBlob=blob;if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(blob);$('#record-preview').src=recordUrl;$('#record-preview').hidden=false;$('#save-recording').disabled=false;$('#record-toggle').classList.remove('recording');$('#record-toggle').innerHTML=icon('mic');$('#record-toggle').setAttribute('aria-label','Record again');$('#record-status').textContent='Listen back, then save your recording.'};mediaRecorder.start();recordSeconds=0;$('#record-preview').hidden=true;$('#save-recording').disabled=true;button.classList.add('recording');button.innerHTML=icon('stop');button.setAttribute('aria-label','Stop recording');$('#record-status').textContent='Recording… 0 seconds. Tap to stop.';recordTimer=setInterval(()=>{recordSeconds++;$('#record-status').textContent='Recording… '+recordSeconds+' seconds. Tap to stop.';if(recordSeconds>=45)mediaRecorder.stop()},1000)
 }catch{if($('#record-status'))$('#record-status').textContent='Microphone access wasn’t available. Allow access in your browser, or choose an audio file.'}finally{if($('#record-toggle'))$('#record-toggle').disabled=false}
}
async function saveRecording(id){if(!pendingBlob)return;try{await recordingStore('readwrite',s=>s.put({id,blob:pendingBlob}));const p=state.phrases.find(x=>x.id===id);p.recordedLanguage=state.profile.language;p.recordedBy=state.profile.caregiver;persist();await refreshRecordings();closeModal();navigate();toast('A familiar voice, saved for '+p.label.toLowerCase()+'.')}catch{toast('This browser could not save audio. Try another browser or free some space.')}}
function helpModal(){showModal('A little guidance.','<p class="modal-description">Sauti is a shared space for a person with aphasia and the people who care for them.</p><div class="modal-points">'+[
 ['grid','Start with something they need.','On the Need board, tap a picture to play its phrase. Recognisable personal photos can help.'],
 ['mic','Make it your family’s voice.','In the Caregiver studio, record each phrase in the language you use at home. English device speech is only a demo preview.'],
 ['sprout','Practise when it feels right.','Try a short, caregiver-guided session. Wait patiently. A word, gesture, or point can all be a successful message.'],
 ['download','Keep a copy.','The demo saves to this browser. Export a backup from the studio to keep your photos, voice recordings, and progress.']
 ].map(([s,t,d])=>'<div class="modal-point"><span>'+icon(s)+'</span><div><strong>'+t+'</strong><p>'+d+'</p></div></div>').join('')+'</div><p class="field-hint" style="margin-top:24px">This prototype has no therapist portal or clinical validation. Rehabilitation activities should be reviewed with a speech-language therapist.</p><div class="modal-actions"><button class="primary-button" data-action="close">Let’s begin '+icon('arrow')+'</button></div>')}
function blobToData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
async function exportBackup(){try{const recordings=db?await allRecordings():[];const data={format:'sauti-backup',version:1,created:new Date().toISOString(),state,recordings:await Promise.all(recordings.map(async x=>({id:x.id,data:await blobToData(x.blob)})))};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='sauti-household-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your backup includes photos, recordings, and progress.')}catch{toast('Could not create a full backup. Please try again.')}}
function importModal(){showModal('Bring your space back.','<p class="modal-description">Choose a Sauti backup. Restoring it replaces this browser’s household, phrase library, recordings, and progress.</p><label class="field">Sauti backup file<input id="backup-upload" type="file" accept=".json,application/json"></label><div class="modal-actions"><button class="secondary-button" data-action="close">Cancel</button><button id="restore-button" class="primary-button" disabled>Restore this backup '+icon('upload')+'</button></div>')}
function validBackup(d){return d?.format==='sauti-backup'&&d.version===1&&d.state?.version===1&&typeof d.state.profile?.patient==='string'&&!!d.state.profile.patient.trim()&&typeof d.state.profile?.caregiver==='string'&&!!d.state.profile.caregiver.trim()&&typeof d.state.profile?.language==='string'&&Array.isArray(d.state.phrases)&&d.state.phrases.length<=100&&d.state.phrases.every(p=>p&&typeof p.id==='string'&&typeof p.label==='string'&&typeof p.phrase==='string'&&typeof p.category==='string'&&Object.hasOwn(drawings,p.symbol)&&(!p.photo||/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+\/=\r\n]+$/.test(p.photo)))&&new Set(d.state.phrases.map(p=>p.id)).size===d.state.phrases.length&&Array.isArray(d.state.sessions)&&d.state.sessions.every(s=>typeof s.date==='string'&&Number.isFinite(Date.parse(s.date))&&Array.isArray(s.attempts)&&s.attempts.every(a=>a&&typeof a.id==='string'&&['independent','supported','try-again'].includes(a.result)))&&Array.isArray(d.state.uses)&&Array.isArray(d.recordings)&&d.recordings.length<=100&&d.recordings.every(r=>typeof r.id==='string'&&typeof r.data==='string'&&/^data:audio\/[a-zA-Z0-9.+;=-]+;base64,/.test(r.data))}
async function restoreBackup(file){if(!file)return;try{if(file.size>60*1024*1024)throw Error('large');const data=JSON.parse(await file.text());if(!validBackup(data))throw Error('invalid');if(!db&&data.recordings.length)throw Error('Audio storage unavailable');const records=await Promise.all(data.recordings.map(async r=>({id:r.id,blob:await(await fetch(r.data)).blob()})));if(db)await new Promise((resolve,reject)=>{const tx=db.transaction('audio','readwrite'),s=tx.objectStore('audio');s.clear();records.forEach(r=>s.put(r));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});state=data.state;state.level=Math.min(2,Math.max(0,Number(state.level)||1));persist();await refreshRecordings();selectedId=state.phrases[0]?.id;session=null;closeModal();navigate();toast('Your household space is back.')}catch{toast('That backup could not be restored. Choose a valid Sauti backup.')}}
async function resizePhoto(file){if(file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG, or WebP photo under 10 MB.');const bitmap=await createImageBitmap(file),scale=Math.min(1,600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.8)}
document.addEventListener('click',async event=>{
 const phrase=event.target.closest('[data-phrase]');if(phrase){selectedId=phrase.dataset.phrase;renderGrid();renderSelected();speak(selectedId);return}
 const filter=event.target.closest('[data-category]');if(filter){category=filter.dataset.category;needPage();return}
 const start=event.target.closest('[data-start]');if(start){startSession(start.dataset.start);return}
 const result=event.target.closest('[data-result]');if(result){rateAttempt(result.dataset.result);return}
 const b=event.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;
 switch(b.dataset.action){
 case 'patient-view':document.body.classList.toggle('patient-view');document.querySelectorAll('.patient-toggle span').forEach(el=>el.textContent=document.body.classList.contains('patient-view')?'Caregiver view':'Patient view');break;case 'settings':settingsModal();break;case 'add':phraseModal();break;case 'edit':phraseModal(id);break;case 'record':recordModal(id);break;case 'speak':speak(id);break;case 'close':closeModal();break;case 'toggle-record':toggleRecord();break;case 'save-recording':saveRecording(id);break;
 case 'practice-listen':if(session)speak(session.queue[session.index].id,true);break;
 case 'cue':if(session){session.cueShown=true;$('#practice-cue').hidden=false}break;
 case 'pause':stopAudio();showModal('A pause is part of the process.','<p class="modal-description">Take all the time you need. Continue when you’re ready, or finish for now. Completed sessions appear in your progress.</p><div class="modal-actions"><button class="secondary-button" data-action="end-session">Finish for now</button><button class="primary-button" data-action="close">Keep practising</button></div>');break;
 case 'end-session':session=null;closeModal();practicePage();break;case 'finish-practice':session=null;practicePage();break;case 'view-progress':session=null;break;
 case 'export':exportBackup();break;case 'import':importModal();break;
 case 'delete-phrase':showModal('Remove this phrase?','<p class="modal-description">This removes the phrase, its photo, and its recording from your board. Your earlier practice moments are kept.</p><div class="modal-actions"><button class="secondary-button" data-action="close">Keep it</button><button class="primary-button" data-action="confirm-delete" data-id="'+esc(id)+'">Remove phrase</button></div>');break;
 case 'confirm-delete':try{if(db)await recordingStore('readwrite',s=>s.delete(id));state.phrases=state.phrases.filter(p=>p.id!==id);if(selectedId===id)selectedId=state.phrases[0]?.id;persist();await refreshRecordings();session=null;closeModal();navigate();toast('Phrase removed.')}catch{toast('Could not remove that phrase. Try again.')}break;
 case 'remove-recording':try{await recordingStore('readwrite',s=>s.delete(id));recordingIds.delete(id);const p=state.phrases.find(x=>x.id===id);delete p.recordedLanguage;delete p.recordedBy;persist();closeModal();navigate();toast('Recording removed. The English sample is available again.')}catch{toast('Could not remove that recording.')}break;
 }
});
document.addEventListener('submit',event=>{
 if(event.target.id==='settings-form'){event.preventDefault();const f=new FormData(event.target),profile={patient:String(f.get('patient')).trim(),caregiver:String(f.get('caregiver')).trim(),language:String(f.get('language')).trim(),pace:Number(f.get('pace'))};if(!profile.patient||!profile.caregiver||!profile.language){toast('Please fill in each name and language.');return}state.profile=profile;persist();closeModal();navigate();toast('Your household space, updated.')}
 if(event.target.id==='phrase-form'){event.preventDefault();const f=new FormData(event.target),id=event.target.dataset.id,old=state.phrases.find(p=>p.id===id),p={...(old||{}),id:id||crypto.randomUUID(),label:String(f.get('label')).trim(),phrase:String(f.get('phrase')).trim(),category:String(f.get('category')),symbol:String(f.get('symbol')),cue:String(f.get('cue')).trim()};if(!p.label||!p.phrase){toast('Add a label and a phrase first.');return}if(pendingPhoto!==undefined)p.photo=pendingPhoto;if(old)state.phrases=state.phrases.map(x=>x.id===id?p:x);else state.phrases.push(p);selectedId=p.id;persist();closeModal();navigate();toast('A familiar phrase, saved.')}
});
document.addEventListener('input',e=>{if(e.target.id==='phrase-search'){search=e.target.value;renderStudioRows()}});
document.addEventListener('change',async e=>{
 if(e.target.id==='photo-upload'){const file=e.target.files[0];if(!file)return;try{pendingPhoto=await resizePhoto(file);$('#photo-status').textContent='Your photo is ready. Save the phrase to keep it.'}catch(error){toast(error.message)}}
 if(e.target.id==='audio-upload'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('audio/')||file.size>5*1024*1024){toast('Choose an audio file under 5 MB.');return}pendingBlob=file;if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(file);$('#record-preview').src=recordUrl;$('#record-preview').hidden=false;$('#save-recording').disabled=false;$('#record-status').textContent='Your audio is ready. Listen back, then save it.'}
 if(e.target.id==='backup-upload'){const file=e.target.files[0];$('#restore-button').disabled=!file;$('#restore-button').onclick=()=>restoreBackup(file)}
});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal()});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
$('#household-settings').innerHTML=icon('chevron');$('#household-settings').onclick=settingsModal;$('#profile-button').onclick=settingsModal;$('#help-button').onclick=helpModal;
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
window.addEventListener('hashchange',navigate);
function connection(){const ready=!!navigator.serviceWorker?.controller;$('#connection-status').innerHTML='<span></span> '+(!navigator.onLine?'Offline · On this device':ready?'Ready for offline':'On this device')}
window.addEventListener('online',connection);window.addEventListener('offline',connection);
if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js').then(()=>{connection();navigator.serviceWorker.addEventListener('controllerchange',connection)}).catch(()=>{});
navigate();
openDatabase().then(async d=>{db=d;await refreshRecordings();if(!modal.open)navigate()}).catch(()=>toast('Audio saving is unavailable in this browser. Other demo features still work.'));
connection();

